import assert from 'node:assert/strict';
import test from 'node:test';
import { findSignatureFields } from './offerLetterFields.mjs';

// The positions pdf.js reports for the acceptance block of a letter generated by the portal (A4).
const block = (runs) => [{ width: 595.28, height: 841.89, runs }];
const run = (text, x, y, width, size = 10) => ({ text, x, y, width, size });

test('places the signature on the line of the acceptance block, beside the name printed above', () => {
  const fields = findSignatureFields(block([
    run('Authorized Signatory', 48, 548.89, 100),
    run('ACCEPTANCE OF OFFER', 48, 486.09, 145.78, 12),
    run('Employee Name:', 48, 426.39, 76.19),
    run('Moraj SAHU', 127, 426.39, 55),
    run('Signature: _______________________________', 48, 411.89, 220.22),
    run('Date: ____________________________________', 48, 397.39, 230),
    run('Place: ____________________________________', 48, 382.89, 236),
  ]));
  assert.ok(fields);
  assert.equal(fields.page, 0);
  assert.ok(fields.signature.x >= 188 && fields.signature.x + fields.signature.width <= 268.3, JSON.stringify(fields.signature));
  assert.equal(fields.signature.height, 30);
  assert.ok(fields.date && fields.date.x > 70 && Math.abs(fields.date.y - 398.39) < 0.01);
  assert.ok(fields.place && fields.place.y < fields.date.y);
});

test('a date and place already printed are left alone', () => {
  const fields = findSignatureFields(block([
    run('Signature: _______________________________', 48, 411.89, 220.22),
    run('Date: 21/11/2026', 48, 397.39, 80),
    run('Place: RAIPUR', 48, 382.89, 70),
  ]));
  assert.ok(fields);
  assert.ok(fields.signature.x >= 96 && fields.signature.x < 100);
  assert.equal(fields.date, null);
  assert.equal(fields.place, null);
});

test('no signature line, no fields', () => {
  assert.equal(findSignatureFields(block([run('Authorized Signatory', 48, 500, 100)])), null);
  assert.equal(findSignatureFields([]), null);
});
